										if(input.Customer_Type == null || input.Customer_Type == "")
										{
											alert "Please select Customer Type.";
											cancel submit;
										}
										// Cash customer validation
										if(input.Customer_Type == "Cash")
										{
											if(input.Customer_Name == null || input.Customer_Name.trim() == "")
											{
												alert "Please enter Customer Name.";
												cancel submit;
