											input.Credit_Allowed = false;
											input.Credit_Limit = 0;
											input.Credit_Days_Allowed = 0;
											input.Current_Outstanding_Balance = 0;
											input.Available_Credit = 0;
											input.Credit_Status = "Good Standing";
											// Customer Code generation - Cash only
											if(input.Customer_Code == null || input.Customer_Code == "")
											{
												count = Customer_Register.count();
												next_no = count + 1;
												if(next_no < 10)
												{
													num_text = "00" + next_no;
												}
												else if(next_no < 100)
												{
													num_text = "0" + next_no;
												}
												else
												{
													num_text = "" + next_no;
												}
												input.Customer_Code = "CP" + num_text;
											}
										}
										// Credit customer validation
										if(input.Customer_Type == "Credit")
										{
											if(input.Customer == null)
											{
												alert "Please select Customer.";
												cancel submit;
											}
											input.Customer_Name = input.Customer.Party_Name_ID;
											input.Display_Name_Customer = input.Customer.Party_Name_ID;
											// Credit customers must not have Customer Code
											input.Customer_Code = "";
										}
										// Display Name Customer
										if(input.Customer_Type == "Cash")
										{
											input.Display_Name_Customer = input.Customer_Name + " - " + input.Customer_Code;
										}
										else if(input.Customer_Type == "Credit")
										{
											input.Display_Name_Customer = input.Customer_Name;
										}
										// Tax Invoice validation
										if(input.Tax_Invoice_Required == true)
										{
											if(input.TIN_Number == null || input.TIN_Number.trim() == "")
											{
												alert "Please enter TIN Number because Tax Invoice is required.";
												cancel submit;
											}
										}
										else
										{
											input.TIN_Number = "";
										}
										// Credit calculations
										input.Current_Outstanding_Balance = ifnull(input.Current_Outstanding_Balance,0);
										input.Credit_Limit = ifnull(input.Credit_Limit,0);
										input.Available_Credit = input.Credit_Limit - input.Current_Outstanding_Balance;
										if(input.Credit_Allowed == true)
										{
											if(input.Current_Outstanding_Balance > input.Credit_Limit)
											{
												input.Credit_Status = "Over Limit";
											}
											else
											{
												input.Credit_Status = "Good Standing";
											}
										}
										else
										{
											input.Credit_Status = "On Hold";
										}

