// ---- CONFIGURE DAY WINDOW HERE ----
										START_DAY_HOUR = 6;
										// 06:00 inclusive
										END_DAY_HOUR = 18;
										// 18:00 exclusive
										// If Date-Time In is cleared, clear dependent fields
										if(input.Date_Time_In == null)
										{
											input.Shift = null;
											input.Hours_Worked = null;
										}
										else
										{
											// -------------------------
											// 1) Shift
											// -------------------------
											hr = input.Date_Time_In.toString("HH").toLong();
											if(hr >= START_DAY_HOUR && hr < END_DAY_HOUR)
											{
												input.Shift = "Day Shift";
											}
											else
											{
												input.Shift = "Night Shift";
											}
											// -------------------------
											// 2) Hours Worked (only if Out exists)
											// -------------------------
											if(input.Date_Time_Out != null)
											{
												// Validate ordering
												if(input.Date_Time_Out < input.Date_Time_In)
												{
													alert "Date-Time Out cannot be earlier than Date-Time In.";
													input.Date_Time_Out = null;
													input.Hours_Worked = null;
												}
												else
												{
													ms = input.Date_Time_Out.toLong() - input.Date_Time_In.toLong();
													input.Hours_Worked = (ms / (1000.0 * 60.0 * 60.0)).round(2);
												}
											}
											else
											{
												input.Hours_Worked = null;
											}
										}

// Voucher → On Date_Time_Out
										// If cleared
										if(input.Date_Time_Out == null)
										{
											input.Hours_Worked = null;
											return;
										}
										// Must have In first
										if(input.Date_Time_In == null)
										{
											alert "Please enter Date-Time In first.";
											input.Date_Time_Out = null;
											input.Hours_Worked = null;
											return;
										}
										// Validate ordering
										if(input.Date_Time_Out < input.Date_Time_In)
										{
											alert "Date-Time Out cannot be earlier than Date-Time In.";
											input.Date_Time_Out = null;
											input.Hours_Worked = null;
											return;
										}
										// Compute hours
										ms = input.Date_Time_Out.toLong() - input.Date_Time_In.toLong();
										input.Hours_Worked = (ms / (1000.0 * 60.0 * 60.0)).round(2);

