											transfer_payload.put("Quantity_in_Base_Unit_Of_Measure",ifnull(input.Quantity_in_Base_Unit_Of_Measure,0.0));
											transfer_payload.put("Issued_By",ifnull(input.Display_Name_Issued_By,""));
											transfer_payload.put("Stock_Condition",cond);
											transfer_payload.put("Unit_Cost",ifnull(input.Cost,0.0));
											transfer_payload.put("Transfer_Status","Not Received");
											transfer_resp = store_management.stock_transfer.create_transfer_from_item_issuing(transfer_payload);
											info transfer_resp;
											if(transfer_resp == null || transfer_resp.get("ok") != true)
											{
												info "Stock was deducted, but Stock Transfer creation failed: " + ifnull(transfer_resp.get("message"),"No response from Store Management.");
												return;
											}
										}
										// =====================================================
										// 12) UPDATE SALES VOUCHER DETAILS ISSUE STATUS
										// =====================================================
										if(input.Request_Voucher_Type == "Sales Voucher" && input.Item_Taken != null)
										{
											svd = Sales_Voucher_Details[ID == input.Item_Taken];
											if(svd.ID != null)
											{
												total_issued_base = 0.0;
												for each  issue in Item_Issuing_Details[Item_Taken == svd.ID]
												{
													total_issued_base = total_issued_base + ifnull(issue.Quantity_in_Base_Unit_Of_Measure,0.0);
												}
												required_base = ifnull(svd.Quantity_in_Base_Unit_Of_Measure,0.0);
												svd.Quantity_Issued_in_Base_Unit_Of_Measure=total_issued_base;
												not_issued_base = required_base - total_issued_base;
												if(not_issued_base < 0)
												{
													not_issued_base = 0.0;
												}
												svd.Quantity_Not_Issued_in_Base_Unit_Of_Measure=not_issued_base;
												if(total_issued_base <= 0)
												{
													svd.Issue_Status="Not Issued";
												}
												else if(total_issued_base >= required_base)
												{
													svd.Issue_Status="Fully Issued";
												}
												else
												{
													svd.Issue_Status="Partially Issued";
												}
											}
										}
										// =====================================================
										// 13) CREATE / UPDATE EMPLOYEE ISSUING DETAILS
										// =====================================================
										source_form_val = "Item Issuing Details";
										if(input.Request_Voucher_Type == "Employee Voucher" && input.Employee_Voucher != null)
										{
											existing_eid = Employee_Issuing_Details[Source_Record_ID == input.ID && Source_Form == source_form_val];
											if(existing_eid.ID != null)
											{
												existing_eid.Voucher=input.Employee_Voucher;
												existing_eid.Display_Name_Voucher=input.Request_Voucher;
												existing_eid.Line_Number=input.Line_Number;
												existing_eid.Display_Name_Item=input.Display_Name_Item;
												existing_eid.Quantity=input.Quantity;
												existing_eid.Cost=input.Cost;
												existing_eid.Item_Issuing_Detail=input.Item_Issuing_Number;
												existing_eid.Source_Record_ID=input.ID;
												existing_eid.Source_Form=source_form_val;
											}
											else
											{
