												stock_resp = store_management.stock.issue_stock_from_masaka_site_management(input.Item,store_id,input.Quantity,input.Unit_Of_Measure,cond,line_total_val,ref_no,input.ID);
												info stock_resp;
												if(stock_resp == null || stock_resp.get("ok") != true)
												{
													input.Status = saved_status;
													info "Stock issue failed: " + ifnull(stock_resp.get("message"),"No response from Store Management.");
													return;
												}
												input.Quantity_in_Base_Unit_Of_Measure = ifnull(stock_resp.get("base_qty"),base_qty_create);
												input.Store_Available_Stock = ifnull(stock_resp.get("store_stock"),0.0);
												input.Global_Available_Stock = ifnull(stock_resp.get("global_stock"),0.0);
											}
											else
											{
												info "No stock deduction. Stock only deducts when saved status is Approved and final status becomes Issued.";
											}
											if(input.Request_Voucher_Type == "Work Order Task" && input.Work_Order_Task != null)
											{
												qty_selected = ifnull(input.Quantity,0.0);
												qty_base = ifnull(input.Quantity_in_Base_Unit_Of_Measure,0.0);
												base_unit_cost = ifnull(input.Cost,0.0);
												selected_uom_name = ifnull(input.Display_Name_Unit_Of_Measure,"");
												if(qty_base <= 0)
												{
													qty_base = base_qty_create;
													input.Quantity_in_Base_Unit_Of_Measure = qty_base;
												}
												rate_base = base_unit_cost;
												line_total_val = (qty_base * base_unit_cost).round(2);
												input.Line_Total = line_total_val;
												description_txt = "";
												description_txt = description_txt + "Issued By: " + ifnull(input.Display_Name_Issued_By,"");
												description_txt = description_txt + "\nStore: " + ifnull(input.Store,"");
												description_txt = description_txt + "\nItem Issuing Number: " + ifnull(input.Item_Issuing_Number,"");
												description_txt = description_txt + "\nTaken By: " + ifnull(input.Display_Name_Taken_By,"");
												description_txt = description_txt + "\nIssued Quantity: " + qty_selected + " " + selected_uom_name;
												pc_exists = false;
												for each  pc_chk in Parts_Consumables[Source_Record_ID == input.ID.toString() && Source_Form == "Item Issuing Details"]
												{
													pc_exists = true;
													pc_chk.Work_Order_Task_Number=input.Work_Order_Task;
													pc_chk.Display_Name_Work_Order_Task_Number=ifnull(input.Work_Order_Task.Work_Order_Task_Number,"");
													pc_chk.Line_Number=input.Line_Number;
													pc_chk.Item=input.Item;
													pc_chk.Display_Name_Item_Labour=ifnull(input.Display_Name_Item,"");
													pc_chk.Description=description_txt;
													pc_chk.Quantity=qty_selected;
													pc_chk.Quantity_In_Base_Unit=qty_base;
													pc_chk.Unit_Of_Measure=selected_uom_name;
													pc_chk.Unit_Cost=base_unit_cost;
													pc_chk.Rate_In_Base_Unit=base_unit_cost;
													pc_chk.Line_Total=line_total_val;
													pc_chk.Item_Issuing=input.ID;
													pc_chk.Item_Status=input.Status;
													break;
												}
												if(pc_exists == false)
												{
													insert into Parts_Consumables
													[
														Work_Order_Task_Number=input.Work_Order_Task
														Display_Name_Work_Order_Task_Number=ifnull(input.Work_Order_Task.Work_Order_Task_Number,"")
														Line_Number=input.Line_Number
														Item=input.Item
														Display_Name_Item_Labour=ifnull(input.Display_Name_Item,"")
														Description=description_txt
														Quantity=qty_selected
														Quantity_In_Base_Unit=qty_base
														Unit_Of_Measure=selected_uom_name
														Unit_Cost=base_unit_cost
														Rate_In_Base_Unit=base_unit_cost
														Line_Total=line_total_val
														Item_Issuing=input.ID
														Item_Status=input.Status
														Source_Record_ID=input.ID.toString()
														Source_Form="Item Issuing Details"
														Added_User=zoho.loginuser
													]
												}
											}
											info "Masaka non-employee request finalized. Final status = " + input.Status;
											return;
										}
										// 6) EMPLOYEE VOUCHER REQUIRED FIELDS
										if(input.Issuing_Voucher == null)
										{
											info "Issuing Voucher is required.";
											return;
										}
										if(input.Employee_Voucher == null)
										{
											info "Employee Voucher is required.";
											return;
										}
										if(input.Item == null || input.Unit_Of_Measure == null || input.Quantity == null || input.Quantity <= 0)
										{
											info "Item, Unit of Measure and Quantity are required.";
											return;
										}
										// 7) LOAD ISSUING HEADER + STORE
										hdr = Item_Issuing_Voucher[ID == input.Issuing_Voucher];
										if(hdr.ID == null || hdr.Store == null)
										{
											info "Header missing or Store missing.";
											return;
										}
										store_id = hdr.Store;
										// 8) STOCK CONDITION
										cond = ifnull(input.Stock_Condition,"New").trim();
										if(cond == "")
										{
											cond = "New";
											input.Stock_Condition = "New";
										}
										// 9) UOM CHECK + BASE QUANTITY
										check = store_management.po.check_uom_conversion_from_masaka_site_management(input.Item,input.Unit_Of_Measure);
										if(check == null || check.get("ok") != true)
										{
											info ifnull(check.get("message"),"UOM conversion failed.");
											return;
										}
										base_qty = store_management.po.convert_to_base_qty_from_masaka_site_management(input.Item,input.Unit_Of_Measure,input.Quantity);
										if(base_qty == null || base_qty <= 0)
										{
											info "Invalid base quantity.";
											return;
										}
										input.Quantity_in_Base_Unit_Of_Measure = base_qty;
										// 10) LINE TOTAL
										line_total_val = (base_qty * ifnull(input.Cost,0.0)).round(2);
										input.Line_Total = line_total_val;
										// 11) TOOL CHECK + FINAL STATUS
										is_tool_item = false;
										if(input.Item != null && input.Item.Is_Tool == true)
										{
											is_tool_item = true;
										}
										if(is_tool_item == true)
										{
											if(input.Didn_t_Come_Back == true)
											{
												input.Status = "Out of Service";
												input.Expected_Return_Date = null;
											}
											else
											{
												issued_base = ifnull(input.Quantity_in_Base_Unit_Of_Measure,0.0);
												returned_base = ifnull(input.Quantity_Returned_in_Base_Unit_Of_Measure,0.0);
												if(issued_base > 0 && returned_base >= issued_base)
												{
													input.Status = "Returned";
													input.Expected_Return_Date = null;
												}
												else
												{
													input.Status = "Borrowed";
												}
											}
										}
										else
										{
											input.Status = "Issued";
											input.Expected_Return_Date = null;
										}
