											alert msg;
											cancel submit;
										}

// =======================================
										// Stock Receiving Voucher Validation
										// On Create / On Validate
										// =======================================
										// 1) Stock Receiving Book required
										if(input.Stock_Receiving_Book == null)
										{
											alert "Please select Stock Receiving Book.";
											cancel submit;
										}
										// 2) Store required
										if(input.Store == null)
										{
											alert "Please select the Store.";
											cancel submit;
										}
										// 3) Received By required
										if(input.Received_By == null || input.Received_By.trim() == "")
										{
											alert "Received By is required.";
											cancel submit;
										}
										// 4) Prevent duplicate Stock Receiving Book only
										existing_rec = Stock_Receiving_Voucher[Stock_Receiving_Book == input.Stock_Receiving_Book && ID != input.ID];
										if(existing_rec.ID != null)
										{
											alert "This Stock Receiving Book has already been used.";
											cancel submit;
										}

// =======================================
										// Bill (Parent) - ON VALIDATE
										// =======================================
										// =======================================
										// BILL DATE VALIDATION
										// =======================================
										if(input.Bill_Date == null)
										{
											alert "Bill Date is required.";
											cancel submit;
										}
										if(input.Bill_Date > zoho.currentdate && input.Billed == true)
										{
											alert "A future dated Bill cannot be marked as Billed.";
											cancel submit;
										}
										if(input.Bill_Type == "External Bill")
										{
											if(input.Vendor == null)
											{
												alert "Vendor is required for Store Bill.";
												cancel submit;
											}
										}
										else if(input.Bill_Type == "Employee Bill")
										{
											if(input.Employee_Vendor == null)
											{
												alert "Employee Vendor is required for Employee Bill.";
												cancel submit;
											}
										}
										else if(input.Bill_Type == "Sales Voucher Bill")
										{
											if(input.Sales_Voucher == null)
											{
												alert "Sales Voucher is required for Sales Voucher Bill.";
												cancel submit;
											}
										}
										if(isnull(input.Bill_Name) || input.Bill_Name.trim() == "")
										{
											alert "Bill Name is required.";
											cancel submit;
										}
										if(isnull(input.Bill_Number) || input.Bill_Number.trim() == "")
										{
											alert "Bill Number is required.";
											cancel submit;
										}
										// ===============================
										// PREVENT DUPLICATE BILL ENTRY
										// ===============================
										if(input.Bill_Type == "Store Bill")
										{
											dup = Bill[Bill_Number == input.Bill_Number && Bill_Name == input.Bill_Name && Vendor == input.Vendor && Bill_Type == input.Bill_Type && ID != input.ID];
											if(dup.count() > 0)
											{
												alert "Duplicate Store Bill detected.";
												cancel submit;
											}
										}
										else if(input.Bill_Type == "Employee Bill")
										{
											dup = Bill[Bill_Number == input.Bill_Number && Bill_Name == input.Bill_Name && Employee_Vendor == input.Employee_Vendor && Bill_Type == input.Bill_Type && ID != input.ID];
											if(dup.count() > 0)
											{
												alert "Duplicate Employee Bill detected.";
												cancel submit;
											}
										}
										else if(input.Bill_Type == "Sales Voucher Bill")
										{
											dup = Bill[Bill_Number == input.Bill_Number && Bill_Name == input.Bill_Name && Sales_Voucher == input.Sales_Voucher && Bill_Type == input.Bill_Type && ID != input.ID];
											if(dup.count() > 0)
											{
												alert "Duplicate Sales Voucher Bill detected.";
												cancel submit;
											}
										}
										// =======================================
										// VALIDATE BILL DETAILS TOTAL
										// =======================================
										if(!input.Bill_Number.contains("Month"))
										{
											details_total = 0.0;
											for each  det in input.Bill_Details
											{
												details_total = details_total + ifnull(det.Line_Total,0.0);
											}
											if(details_total > ifnull(input.Bill_Total,0.0))
											{
												alert "Details exceed Bill Total!";
												cancel submit;
											}
										}

// =======================================
										// Concrete Bill Details
										// =======================================
										errors = List();
										is_store_bill = false;
										is_parts_bill = false;
										is_document_transport = false;
										// -------------------------------
										// 1) Detect Bill Detail Type
										// -------------------------------
										if(input.Expense_Type == "Document Transport")
										{
											is_document_transport = true;
										}
										else if(input.Stock_Receiving_Details != null)
										{
											is_store_bill = true;
										}
										else if(input.Parts_Consumables != null)
										{
											is_parts_bill = true;
										}
										if(input.Bill == null)
										{
											errors.add("• Bill is required.");
										}
										// =====================================================
										// A) DOCUMENT TRANSPORT
										// =====================================================
										if(is_document_transport)
										{
											if(input.Details_Date == null)
											{
												errors.add("• Details Date is required.");
											}
											if(input.Reference == null || input.Reference.trim() == "")
											{
												errors.add("• Reference is required.");
											}
											if(input.Details == null || input.Details.trim() == "")
											{
												errors.add("• Details is required.");
											}
											if(input.Quantity == null || input.Quantity <= 0)
											{
												errors.add("• Quantity must be greater than 0.");
											}
											if(input.Rate == null || input.Rate < 0)
											{
												errors.add("• Rate is required.");
											}
											if(input.Account == null || input.Account.trim() == "")
											{
												errors.add("• Account is required.");
											}
										}
										// =====================================================
										// B) STORE BILL DETAILS ONLY
										// =====================================================
										else if(is_store_bill)
										{
											if(input.Item == null)
											{
												errors.add("• Item is required.");
											}
											if(input.Unit_Of_Measure == null)
											{
												errors.add("• Unit Of Measure is required.");
											}
											if(input.Quantity == null || input.Quantity <= 0)
											{
												errors.add("• Quantity must be greater than 0.");
											}
											if(input.Rate == null || input.Rate < 0)
											{
												errors.add("• Rate is required.");
											}
											billable = ifnull(input.Quantity_Billable,0.0);
											if(input.Quantity != null && input.Quantity > billable)
											{
												errors.add("• You cannot bill more than Quantity Billable (" + billable.toString() + ").");
											}
											base_qty = ifnull(input.Quantity_In_Base_Unit,0.0);
											if(base_qty <= 0 && input.Item != null && input.Unit_Of_Measure != null && input.Quantity != null && input.Quantity > 0)
											{
												po_det = Purchase_Order_Details[ID == input.Item];
												if(po_det.ID != null && po_det.Item != null)
												{
													item_id = po_det.Item;
													check = store_management.po.check_uom_conversion_from_concrete(item_id,input.Unit_Of_Measure);
													if(check == null || check.get("ok") != true)
													{
														errors.add("• " + ifnull(check.get("message"),"UOM conversion failed."));
													}
													else
													{
														bq = store_management.po.convert_to_base_qty_from_concrete(item_id,input.Unit_Of_Measure,input.Quantity);
														if(bq != null && bq > 0)
														{
															input.Quantity_In_Base_Unit = bq;
															base_qty = bq;
														}
													}
												}
											}
											if(base_qty <= 0)
											{
												errors.add("• Quantity in Base Unit could not be calculated. Check Unit Of Measure conversion.");
											}
											line_total_val = 0.0;
											if(input.Quantity != null && input.Rate != null)
											{
												line_total_val = round(input.Quantity * input.Rate,2);
											}
											if(line_total_val > 0 && base_qty > 0)
											{
												input.Rate_In_Base_Unit = round(line_total_val / base_qty,2);
											}
											else
											{
												input.Rate_In_Base_Unit = 0.0;
											}
										}
										// =====================================================
										// C) WORK ORDER / PARTS & CONSUMABLES BILL DETAILS
										// =====================================================
										else if(is_parts_bill)
										{
											if(input.Details == null || input.Details.trim() == "")
											{
												errors.add("• Details is required for Parts & Consumables.");
											}
											if(input.Quantity == null || input.Quantity <= 0)
											{
												errors.add("• Quantity must be greater than 0.");
											}
											if(input.Rate == null || input.Rate < 0)
											{
												errors.add("• Rate is required.");
											}
										}
										// =====================================================
										// D) DEFAULT / MANUAL EMPLOYEE DETAILS
										// =====================================================
										else
										{
