										// =====================================================
										// 3) Check Bill Total limit - applies to all bill types
										// =====================================================
										if(input.Bill != null)
										{
											bill_rec = Bill[ID == input.Bill];
											if(bill_rec.ID != null)
											{
												bill_total = ifnull(bill_rec.Bill_Total,0.0);
												if(bill_total <= 0)
												{
													bill_total = ifnull(bill_rec.Amount_Due,0.0);
												}
												allowed_excess = 10.0;
												existing_total = 0.0;
												existing_lines = Bill_Details[Bill == bill_rec.ID];
												for each  row in existing_lines
												{
													if(input.ID != null && row.ID == input.ID)
													{
														continue;
													}
													existing_total = existing_total + ifnull(row.Line_Total,0.0);
												}
												current_line_total = 0.0;
												if(input.Quantity != null && input.Rate != null)
												{
													current_line_total = round(input.Quantity * input.Rate,2);
												}
												else
												{
													current_line_total = ifnull(input.Line_Total,0.0);
												}
												new_total = existing_total + current_line_total;
												excess_amount = new_total - bill_total;
												if(excess_amount > allowed_excess)
												{
													errors.add("• Details Total exceeds Bill Total by " + excess_amount.toString() + ". Maximum allowed excess is 10.");
												}
											}
										}
										if(errors.size() > 0)
										{
											msg = "Please fix the following:\n\n";
											for each  err_msg in errors
											{
												msg = msg + err_msg + "\n";
											}
											alert msg;
											cancel submit;
